  ],\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"dependencies\": {\n    \"@hyzyn/dsh-codegraph\": \"0.6.20\",\n    \"@hyzyn/dsh-docker\": \"0.15.0\",\n    \"@hyzyn/dsh-env\": \"0.3.17\",\n    \"@hyzyn/dsh-kit-settings\": \"0.2.9\",\n    \"@hyzyn/dsh-loglens\": \"0.1.8\",\n    \"@hyzyn/dsh-mcp\": \"0.3.13\",\n    \"@hyzyn/dsh-profile\": \"0.2.15\",\n    \"@hyzyn/dsh-prompt\": \"0.2.15\",\n    \"@hyzyn/dsh-rss\": \"0.4.16\",\n    \"@hyzyn/dsh-search\": \"0.4.18\",\n    \"@hyzyn/dsh-tty\": \"0.38.0\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh\": \"^0.1.7-rc.2 || ^0.2.0-rc.1 || ^0.2.0-rc.2 || ^0.2.1-alpha.1 || ^0.2.1-alpha.2 || ^0.2.1-alpha.5 || ^0.2.1-rc.1 || ^0.2.1-rc.2 || ^0.2.1-rc.3 || ^0.2.1-rc.4 || ^0.2.1-rc.5 || ^0.2.2-alpha.3 || ^0.2.2-rc.1\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh\": {\n      \"optional\": true\n    }\n  },\n  \"pnpm\": {\n    \"overrides\": {\n      \"@deepseek-ai/dsh\": \"link:scripts/dsh-peer-stub\"\n    }\n  }\n}\n"
